from dataclasses import dataclass
from typing import Any, Dict, Optional, Union


DEFAULT_TTS_MODEL = "gpt-4o-mini-tts"
DEFAULT_TTS_VOICE = "alloy"
DEFAULT_AUDIO_FORMAT = "mp3"


def normalize_locale(locale: Optional[str]) -> Optional[str]:
    if locale is None:
        return None
    value = locale.strip().replace("_", "-")
    return value.lower() if value else None


def normalize_voice(voice: Optional[str], default: str = DEFAULT_TTS_VOICE) -> str:
    if voice is None:
        return default
    value = voice.strip()
    return value or default


def normalize_model(model: Optional[str], default: str = DEFAULT_TTS_MODEL) -> str:
    if model is None:
        return default
    value = model.strip()
    return value or default


def normalize_audio_format(audio_format: Optional[str], default: str = DEFAULT_AUDIO_FORMAT) -> str:
    if audio_format is None:
        return default
    value = audio_format.strip().lower()
    return value or default


@dataclass(frozen=True)
class TTSRequest:
    input: str
    model: str = DEFAULT_TTS_MODEL
    voice: str = DEFAULT_TTS_VOICE
    response_format: str = DEFAULT_AUDIO_FORMAT
    speed: Optional[float] = None
    instructions: Optional[str] = None

    def normalized(self) -> "TTSRequest":
        return TTSRequest(
            input=self.input,
            model=normalize_model(self.model),
            voice=normalize_voice(self.voice),
            response_format=normalize_audio_format(self.response_format),
            speed=self.speed,
            instructions=self.instructions.strip() if isinstance(self.instructions, str) and self.instructions.strip() else None,
        )

    def to_api_kwargs(self) -> Dict[str, Any]:
        payload: Dict[str, Any] = {
            "model": normalize_model(self.model),
            "voice": normalize_voice(self.voice),
            "input": self.input,
            "response_format": normalize_audio_format(self.response_format),
        }
        if self.speed is not None:
            payload["speed"] = self.speed
        if self.instructions is not None and self.instructions.strip():
            payload["instructions"] = self.instructions.strip()
        return payload


@dataclass(frozen=True)
class TTSResponse:
    audio: bytes
    model: str = DEFAULT_TTS_MODEL
    voice: str = DEFAULT_TTS_VOICE
    response_format: str = DEFAULT_AUDIO_FORMAT


def normalize_tts_request(
    request: Union[TTSRequest, Dict[str, Any]],
    *,
    default_model: str = DEFAULT_TTS_MODEL,
    default_voice: str = DEFAULT_TTS_VOICE,
    default_audio_format: str = DEFAULT_AUDIO_FORMAT,
) -> TTSRequest:
    if isinstance(request, TTSRequest):
        return TTSRequest(
            input=request.input,
            model=normalize_model(request.model, default_model),
            voice=normalize_voice(request.voice, default_voice),
            response_format=normalize_audio_format(request.response_format, default_audio_format),
            speed=request.speed,
            instructions=request.instructions.strip() if isinstance(request.instructions, str) and request.instructions.strip() else None,
        )
    return TTSRequest(
        input=str(request.get("input", "")),
        model=normalize_model(request.get("model"), default_model),
        voice=normalize_voice(request.get("voice"), default_voice),
        response_format=normalize_audio_format(request.get("response_format"), default_audio_format),
        speed=request.get("speed"),
        instructions=request.get("instructions"),
    ).normalized()


def build_tts_payload(request: Union[TTSRequest, Dict[str, Any]]) -> Dict[str, Any]:
    return normalize_tts_request(request).to_api_kwargs()

import os
from dataclasses import dataclass
from typing import Optional

from openai import OpenAI


DEFAULT_TTS_MODEL = "gpt-4o-mini-tts"
DEFAULT_TTS_VOICE = "alloy"


@dataclass(frozen=True)
class SpeechConfig:
    api_key: Optional[str] = None
    base_url: Optional[str] = None
    organization: Optional[str] = None
    project: Optional[str] = None
    model: str = DEFAULT_TTS_MODEL
    voice: str = DEFAULT_TTS_VOICE


def load_speech_config() -> SpeechConfig:
    return SpeechConfig(
        api_key=os.getenv("OPENAI_API_KEY"),
        base_url=os.getenv("OPENAI_BASE_URL"),
        organization=os.getenv("OPENAI_ORG_ID") or os.getenv("OPENAI_ORGANIZATION"),
        project=os.getenv("OPENAI_PROJECT"),
        model=os.getenv("OPENAI_TTS_MODEL", DEFAULT_TTS_MODEL),
        voice=os.getenv("OPENAI_TTS_VOICE", DEFAULT_TTS_VOICE),
    )


def create_speech_client(config: Optional[SpeechConfig] = None) -> OpenAI:
    cfg = config or load_speech_config()
    kwargs = {}
    if cfg.api_key is not None:
        kwargs["api_key"] = cfg.api_key
    if cfg.base_url is not None:
        kwargs["base_url"] = cfg.base_url
    if cfg.organization is not None:
        kwargs["organization"] = cfg.organization
    if cfg.project is not None:
        kwargs["project"] = cfg.project
    return OpenAI(**kwargs)


def resolve_tts_settings(
    model: Optional[str] = None,
    voice: Optional[str] = None,
    config: Optional[SpeechConfig] = None,
) -> tuple[str, str]:
    cfg = config or load_speech_config()
    return model or cfg.model, voice or cfg.voice

import os
from dataclasses import dataclass
from typing import List, Optional

from openai import OpenAI


@dataclass(frozen=True)
class VoiceOption:
    name: str
    locale: str
    description: str = ""


_OPENAI_VOICES: List[VoiceOption] = [
    VoiceOption(name="alloy", locale="en"),
    VoiceOption(name="echo", locale="en"),
    VoiceOption(name="fable", locale="en-GB"),
    VoiceOption(name="onyx", locale="en"),
    VoiceOption(name="nova", locale="en-US"),
    VoiceOption(name="shimmer", locale="en-US"),
]


def _normalize_locale(locale: str) -> str:
    return locale.replace("_", "-").strip().lower()


def _locale_score(voice_locale: str, target_locale: str) -> int:
    voice_locale = _normalize_locale(voice_locale)
    target_locale = _normalize_locale(target_locale)
    if voice_locale == target_locale:
        return 3
    if voice_locale.split("-")[0] == target_locale.split("-")[0]:
        return 2
    if target_locale.startswith(voice_locale) or voice_locale.startswith(target_locale):
        return 1
    return 0


def list_voices(target_locale: str, api_key: Optional[str] = None) -> List[VoiceOption]:
    client = OpenAI(api_key=api_key or os.getenv("OPENAI_API_KEY"))
    client.models.list()
    normalized = _normalize_locale(target_locale)
    return sorted(_OPENAI_VOICES, key=lambda v: (_locale_score(v.locale, normalized), v.name), reverse=True)


def select_voice(target_locale: str, api_key: Optional[str] = None) -> str:
    voices = list_voices(target_locale, api_key=api_key)
    if not voices:
        raise ValueError("No voices available")
    return voices[0].name

